import { createTheme } from '@mui/material/styles';

const theme = createTheme({
  typography: {
    fontFamily: 'Prompt, sans-serif',
  },
  palette: {
    primary: {
      main: '#0e8d78ff', // เขียวมิ้นต์
    },
    secondary: {
      main: '#272207ff', // สีทองอ่อน (ดาว)
    },
    info:{
      main:'#ffffffff'
    },
    error:{
      main: '#cf3e3eff'
    },
    background: {
      default: '#F5F5F5',
    },
  },
  components: {
    MuiCard: {
      styleOverrides: {
        root: {
          borderRadius: 0, // ไม่มีมุมโค้ง
        },
      },
    },
    MuiButton: {
      styleOverrides: {
        root: {
          borderRadius: 0,
          textTransform: 'none',
          fontWeight: 600,
        },
      },
    },
  },
});

export default theme;
